/**
 * ImFusion Web SDK
 *
 * @example
 * ```ts
 * import { init } from '@imfusion/sdk';
 *
 * const canvas = document.getElementById('canvas') as HTMLCanvasElement;
 * const imf = await init(canvas, { autoResize: true });
 *
 * const data = await imf.loadFileFromUrl('/scans/ct.nii.gz');
 * imf.showAll(data);
 * ```
 *
 * @packageDocumentation
 */
import type { ImFusion, InitOptions } from './imfusion.js';
/**
 * Fetch and compile the SDK's WebAssembly module ahead of {@link init}.
 *
 * The compiled module is cached at the SDK module level. Calling
 * `preloadWasm()` more than once returns the same cached promise; subsequent
 * calls to {@link init} pick up the cached module automatically.
 *
 * @param options.url - URL to fetch the wasm from. Defaults to the wasm co-located with the SDK.
 * @param options.priority - Fetch priority hint. Use `'low'` for background preloading.
 * @returns A promise that resolves to the compiled `WebAssembly.Module`.
 *
 * @example
 * ```ts
 * // main.ts - kick off the wasm fetch as early as possible.
 * import { preloadWasm } from '@imfusion/sdk';
 * preloadWasm();
 *
 * // Later, in a component
 * import { init } from '@imfusion/sdk';
 * const imf = await init(canvas);
 * ```
 */
export declare function preloadWasm(options?: {
    url?: string | URL;
    priority?: RequestPriority;
}): Promise<WebAssembly.Module>;
/**
 * Initialize the ImFusion Web SDK.
 *
 * @param canvas - The canvas element to render into
 * @param options - Optional initialization options
 * @returns Promise resolving to the ImFusion instance
 *
 * @example
 * ```ts
 * // Basic usage
 * const imf = await init(myCanvas);
 *
 * // With auto-resize enabled
 * const imf = await init(myCanvas, { autoResize: true });
 *
 * // With custom DPI scale and manual input handling
 * const imf = await init(myCanvas, {
 *   dpiScale: 2,
 *   autoInputHandling: false,
 * });
 * ```
 *
 * @remarks
 * You can call {@link preloadWasm} ahead of `init()` to initiate the wasm
 * fetch and compilation if canvas is not yet available.
 */
export declare function init(canvas: HTMLCanvasElement, options?: InitOptions): Promise<ImFusion>;
export type { ImFusion, InitOptions, CreateImageOptions, CustomGlObject, ProgressCallback } from './imfusion.js';
export { prefetch, clearPrefetch } from './prefetchCache.js';
export * from '../wasm/ImFusionLib.js';
